import { expect, test } from "bun:test";
import { getWidget } from "./cache";

// The cache is module-scoped and lives for the process, so every test uses ids no other test uses.

test("cached widget: second lookup returns the first lookup's widget", () => {
	const first = getWidget("a");
	expect(getWidget("a")).toBe(first);
	expect(first.id).toBe("a");
});

test("cached widget: empty id is cached like any other id", () => {
	const first = getWidget("");
	expect(getWidget("")).toBe(first);
	expect(first.id).toBe("");
});

test("cached widget: interleaved lookups keep earlier widgets", () => {
	const first = getWidget("i1");
	const second = getWidget("i2");
	expect(getWidget("i1")).toBe(first);
	expect(getWidget("i2")).toBe(second);
});

test("distinct ids return distinct widgets", () => {
	const b1 = getWidget("b1");
	const b2 = getWidget("b2");
	expect(b2).not.toBe(b1);
	expect(b1.id).toBe("b1");
	expect(b2.id).toBe("b2");
});

const widgets = new Map<string, { id: string }>();

export function getWidget(id: string): { id: string } {
	let widget = widgets.get(id);
	if (widget === undefined) {
		widget = { id };
		widgets.set(id, widget);
	}
	return widget;
}

